func (st *ServerType) inspectParsedOption(name string, val interface{}) string {
	st.lastOption = name
	st.surveyOptionCatalogs(name)
	switch name {
	case "http_port":
		if n, ok := val.(int); ok {
			st.rememberPortOption(name, strconv.Itoa(n), n)
			return "http_port"
		}
	case "https_port":
		if n, ok := val.(int); ok {
			st.rememberPortOption(name, strconv.Itoa(n), n)
			return "https_port"
		}
	case "default_bind":
